head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getAllParameter]<br/>URL 쿼리 문자열(GET 방식)의 전체 파라미터를 JSON 객체로 반환합니다.",
    "validation" : [
        "전체 파라미터를 키-값 쌍의 JSON 객체로 반환해야 합니다.",
        "각 값은 URL 디코딩된 상태여야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getAllParameter_onclick = function () {
    var result = $p.getAllParameter();

    // w2xPath 제외
    var filtered = {};
    var keys = Object.keys(result);
    for (var i = 0; i < keys.length; i++) {
        if (keys[i] !== "w2xPath") {
            filtered[keys[i]] = result[keys[i]];
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getAllParameter() (w2xPath 제외) : " + JSON.stringify(filtered));

    var filteredKeys = Object.keys(filtered);
    if (filteredKeys.length > 0) {
        for (var j = 0; j < filteredKeys.length; j++) {
            wf_body_bottom.getObj("scwin").setReturnValue("  " + filteredKeys[j] + " : " + filtered[filteredKeys[j]]);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("추가 파라미터 없음");
    }
}



scwin.btn_navigateWithParam_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("$p.url 로 파라미터 전달하여 이동합니다.");

    $p.url("/sample/p/p_M_getAllParameter_1.xml", {
        spa: false,
        param: {"name": "test", "value": "100"}
    });
}
